#include <cstdio>
const int N = 1e5 + 5;
int fathers[18][N], sons[18][N];
int main() {
    int n, q;
    scanf("%d%d", &n, &q);
    for (int i = 2; i <= n; ++i) {
        int p;
        scanf("%d", &p), fathers[0][i] = p;  
        if (!sons[0][p])  
            sons[0][p] = i;  
    }
    fathers[0][1] = 1;  
    for (int i = 1; i <= n; ++i)
        if (!sons[0][i]) sons[0][i] = i;  
    for (int j = 1; (1 << j) <= n; ++j)  
        for (int i = 1; i <= n; ++i)  
            sons[j][i] = sons[j - 1][sons[j - 1][i]], fathers[j][i] = fathers[j - 1][fathers[j - 1][i]];  
    for (int s, k; q--;) {
        scanf("%d%d", &s, &k);
        for (int a; k--;) {
            scanf("%d", &a);
            if (a > 0) {
                for (int g = 0; (1 << g) <= a; ++g)  
                    if (a & (1 << g))
                        s = fathers[g][s];  
            } else {
                a = -a;
                for (int g = 0; (1 << g) <= a; ++g)  
                    if (a & (1 << g))
                        s = sons[g][s];
            }
        }
        printf("%d\n", s);
    }
}
